// ADR-014: blob: is allowed for images/media generated by the page itself, but a blob URL
// must still not be usable to run script, start a worker or send data out.
(async function () {
  var r = { imageLoaded: false, scriptRan: false, workerStarted: false };
  // 1. Image from a locally generated blob (allowed).
  var svg = new Blob(
    [
      '<svg xmlns="http://www.w3.org/2000/svg" width="4" height="4"><rect width="4" height="4"/></svg>',
    ],
    { type: 'image/svg+xml' },
  );
  await new Promise(function (resolve) {
    var img = new Image();
    img.onload = function () {
      r.imageLoaded = true;
      resolve();
    };
    img.onerror = function () {
      resolve();
    };
    img.src = URL.createObjectURL(svg);
  });
  // 2. Script from a blob URL (must stay blocked by script-src 'self').
  var js = new Blob(['window.__blobScriptRan = true;'], { type: 'text/javascript' });
  var s = document.createElement('script');
  s.src = URL.createObjectURL(js);
  document.head.appendChild(s);
  // 3. Worker from a blob URL (must stay blocked by worker-src 'none').
  try {
    var w = new Worker(URL.createObjectURL(js));
    w.onerror = function () {};
    r.workerStarted = true;
  } catch (e) {
    r.workerError = e.name;
  }
  await window.__wcWaitFor(['script-src-elem', 'worker-src'], 2000);
  r.scriptRan = !!window.__blobScriptRan;
  window.__wcFinish(r);
})();
